def _build_analysis_coverage(metadata: dict, disassemble: bool) -> dict:
    """Account for what was analyzed versus what was discovered.

    A run that disassembled 3 of 400 functions must never be
    indistinguishable from a clean run of 400: automated consumers need the
    blind spots, not just the findings.
    """
    functions = metadata.get('functions') or []
    discovered = metadata.get('discovered_functions') or []
    disassembled = metadata.get('disassembled_functions') or {}
    symbolic_count = 0
    discovered_merged = 0
    for func_entry in functions:
        if not isinstance(func_entry, dict):
            continue
        if func_entry.get('discovered'):
            discovered_merged += 1
        else:
            symbolic_count += 1
    degradations = []
    if metadata.get('disassembly_skipped'):
        degradations.append(metadata['disassembly_skipped'])
    if disassemble and (not disassembled) and (not metadata.get('disassembly_skipped')):
        degradations.append('disassembly_unavailable')
    if metadata.get('is_encrypted'):
        degradations.append('fairplay_encrypted')
    if (metadata.get('link_hygiene') or {}).get('attribution_status') == 'unresolved':
        degradations.append('dependency_attribution_unresolved')
    coverage = {'functions': {'symbolic': symbolic_count, 'discovered': len(discovered), 'discovered_merged_into_function_list': discovered_merged, 'disassembled': len(disassembled)}, 'degradations': sorted(degradations)}
    if (entropy := metadata.get('entropy')):
        sections_analyzed = len(entropy.get('sections') or [])
        coverage['sections_analyzed'] = sections_analyzed
    if (gaps := metadata.get('security_properties_gaps')):
        coverage['security_properties_gaps'] = list(gaps)
    if (variance := metadata.get('security_properties_slice_variance')):
        coverage['security_properties_slice_variance'] = list(variance)
    if (scope := metadata.get('code_signature_scope')):
        coverage['code_signature_scope'] = scope
    if (variance := metadata.get('code_signature_slice_variance')):
        coverage['code_signature_slice_variance'] = list(variance)
    if (metadata.get('code_signature') or {}).get('parse_status') == 'parse_failed':
        degradations.append('code_signature_parse_failed')
        coverage['degradations'] = sorted(degradations)
    slice_summaries = metadata.get('slices') or []
    slice_errors = metadata.pop('slice_errors', [])
    if metadata.get('is_universal'):
        coverage['slices'] = {'total': len(slice_summaries) + len(slice_errors), 'summarized': len(slice_summaries), 'failed': len(slice_errors)}
        if slice_errors:
            coverage['slices']['errors'] = slice_errors
            degradations.append('slice_summary_failed')
            coverage['degradations'] = sorted(degradations)
    return coverage

@staticmethod
def _is_gpt5_reasoning_model(model_name: str) -> bool:
    """Whether the model is a GPT-5.x / o-series reasoning model.

        Covers gpt-5, gpt-5.4/5.5/5.6 (including suffixed variants like
        gpt-5.6-sol / gpt-5.6-luna) and the o1/o3/o4 families. These models
        only accept default sampling params and, on /v1/chat/completions,
        reject reasoning_effort together with function tools.
        """
    if not model_name or not isinstance(model_name, str):
        return False
    name = model_name.lower()
    if name.startswith('gpt-5'):
        return True
    if name.startswith(('o1', 'o3', 'o4')):
        return True
    return False

@staticmethod
def _truncate(value: str, limit: int) -> str:
    """Truncate a long string to ``limit`` chars with an ellipsis.

        ``longBusinessSummary`` (and any other free-text profile field) can run
        to thousands of characters; capping it keeps the agent context compact.
        """
    if limit <= 0 or len(value) <= limit:
        return value
    return value[:limit].rstrip() + '…'

def _make_risk(risk_id: str, description: list[str] | None=None, ext_refs: list[dict] | None=None) -> dict:
    """Build a minimal risk entry dict, optionally with a description and externalReferences."""
    entry: dict = {'id': risk_id, 'title': f'Title {risk_id}'}
    if description is not None:
        entry['description'] = description
    if ext_refs is not None:
        entry['externalReferences'] = ext_refs
    return entry

def _pct(data: list, p: float) -> float:
    """Return the p-th percentile of ``data`` (linear interpolation)."""
    if not data:
        return 0.0
    s = sorted(data)
    k = (len(s) - 1) * p / 100.0
    (lo, hi) = (int(k), min(int(k) + 1, len(s) - 1))
    return s[lo] + (s[hi] - s[lo]) * (k - lo)

def reformat_asterisks(text):
    """
    Fixes Pandas docstring warning about using * and ** without ending \\* and \\*\\*.

    The fix distinguishes single * and ** by adding \\ to them. No changes for *italic* and **bold** usages.

    :param text: Original text with warnings
    :return: Modified text that fixes warnings
    """
    lines = text.split('\n')
    new_text = ''
    for line in lines:
        idx = 0
        while idx < len(line):
            idx1 = line.find('*', idx)
            if idx1 >= idx:
                idx2 = line.find('*', idx1 + 1)
                if idx2 == -1:
                    line = line.replace('*', '\\*')
                    idx = len(line)
                elif idx2 == idx1 + 1:
                    idx2 = line.find('**', idx1 + 2)
                    if idx2 == -1:
                        line = line.replace('**', '\\*\\*')
                        idx = idx1 + 4
                    else:
                        idx = idx2 + 2
                elif idx2 + 1 < len(line):
                    if line[idx2 + 1] == '*':
                        line = line.replace('*', '\\*', 1)
                        idx = idx2
                    else:
                        idx = idx2 + 1
                else:
                    idx = len(line)
            else:
                idx = len(line)
        new_text += line + '\n'
    return new_text

