def parse_frontmatter(text: str) -> tuple[dict, str]:
    """Return (frontmatter, body). Frontmatter values are str or dict[str, str]."""
    lines = text.splitlines()
    if not lines or lines[0].strip() != '---':
        return ({}, text)
    end = None
    for i in range(1, len(lines)):
        if lines[i].strip() == '---':
            end = i
            break
    if end is None:
        return ({}, text)
    fm: dict = {}
    key_re = re.compile('^([A-Za-z0-9_-]+):\\s*(.*)$')
    i = 1
    while i < end:
        raw = lines[i]
        if not raw.strip() or raw.lstrip().startswith('#') or raw[:1] in (' ', '\t'):
            i += 1
            continue
        m = key_re.match(raw)
        if not m:
            i += 1
            continue
        (key, inline) = (m.group(1), m.group(2).strip())
        if inline in ('>', '|', '>-', '|-', '>+', '|+'):
            block: list[str] = []
            j = i + 1
            while j < end and (not lines[j].strip() or lines[j][:1] in (' ', '\t')):
                block.append(lines[j].strip())
                j += 1
            fm[key] = ' '.join((part for part in block if part))
            i = j
            continue
        if inline == '':
            nested: dict[str, str] = {}
            j = i + 1
            while j < end and lines[j][:1] in (' ', '\t') and lines[j].strip():
                sub = key_re.match(lines[j].strip())
                if sub:
                    nested[sub.group(1)] = sub.group(2).strip()
                j += 1
            fm[key] = nested if nested else ''
            i = j
            continue
        fm[key] = inline
        i += 1
    return (fm, '\n'.join(lines[end + 1:]))

def _version_parts(version):
    """A `(major, minor, ...)` int tuple, or None if it cannot be read.

    `is_abi_risk_python_version` unpacks `version[:2]`, so handing it the string
    "3.13.3" yields `("3", ".")` and a quiet False — the interpreter most likely
    to have caused the crash would be reported as not at risk. Normalizing here
    means a caller cannot make that mistake by passing the obvious thing.
    """
    if version is None:
        return None
    if isinstance(version, str):
        try:
            return tuple((int(part) for part in version.split('.')[:3]))
        except ValueError:
            return None
    try:
        return tuple((int(part) for part in tuple(version)[:3]))
    except (TypeError, ValueError):
        return None

def send_napalm_commands(cmds, show_output=False, debug=False):
    """
    For a given list of commands, cmds, execute the napalm_cli method via Nornir Task
    and return a dictionary of dictionaries

    First key = device
    Secondary key(s) = show commands executed via cmds

    show_output is an optional argument which prints out the Ansible-like run output.
    debug is an optional argument which prints out values to assist in debugging.

    :param cmds: list of commands to execute on each device
    :param show_output: Boolean which defaults to False.
        When True values the Ansible-like run output will be printed to stdout
    :param debug: Boolean which defaults to False. When True values will be printed to stdout
    :return: output_dict
    """
    output_dict = {}
    if isinstance(cmds, list):
        nornir_instance = InitNornir(dry_run=True)
        cli_result = nornir_instance.run(napalm_cli, commands=cmds)
        if debug:
            print(cli_result.keys())
        for dev_key in cli_result.keys():
            if debug:
                print(dev_key)
                print(cli_result[dev_key][0].result.keys())
                print(cli_result[dev_key])
                print(dir(cli_result[dev_key]))
                print(cli_result[dev_key][0])
                print(cli_result[dev_key].failed)
                print_result(cli_result)
            if cli_result[dev_key].failed:
                print(cli_result[dev_key][0])
                output_dict.update({dev_key: []})
            else:
                for result_key in cli_result[dev_key][0].result.keys():
                    output_dict.update({dev_key: cli_result[dev_key][0].result[result_key]})
        if debug:
            for (k, v) in output_dict.items():
                print('device: {} \toutput: {}'.format(k, v))
    else:
        print('ERROR! argument passed to function must be a list!  Will return empty dictionary.')
    if show_output:
        print_result(cli_result, vars=['stdout'])
    return output_dict

def _wf_best_accepted_delta_pct(wf: dict) -> float:
    """Largest positive ``e2e_delta_pct`` claimed by an accepted head/kernel.

    The workflow return carries the heads/kernels it ACCEPTED (each with the
    measured same-session A/B ``e2e_delta_pct``). This is the ground-truth signal
    that a real, parity-checked win exists — independent of whatever final
    throughput/speedup the return also reports. Returns 0.0 when nothing claims a
    positive gain.
    """
    best = 0.0
    for item in (wf.get('accepted_heads') or []) + (wf.get('accepted_kernels') or []):
        if not isinstance(item, dict):
            continue
        try:
            d = float(item.get('e2e_delta_pct') or 0.0)
        except (TypeError, ValueError):
            d = 0.0
        if d > best:
            best = d
    return best

def _resolve_field(actual: object, field: str) -> tuple[object, bool]:
    """Return ``(value, present)`` for a dotted ``field`` path into ``actual``."""
    cur = actual
    for part in field.split('.'):
        if isinstance(cur, dict) and part in cur:
            cur = cur[part]
        else:
            return (None, False)
    return (cur, True)

def _default_cell(value):
    """Render a flag default as a code span. Lists become `["a", "b"]` rather
    than a bare `a, b`, which reads ambiguously in a table cell."""
    if value is None or value in ('', []):
        return ''
    if isinstance(value, list | tuple):
        items = ', '.join((f'"{v}"' if isinstance(v, str) else str(v) for v in value))
        text = f'[{items}]'
    else:
        text = str(value)
    safe = ' '.join(text.replace('|', '\\|').split())
    return f'`{safe}`'

def _resolve_max_prompt_tokens(auto_estimate: int, explicit_limit: int | None) -> int:
    """Resolve the prompt/context token cap enforced before prefill.

    ``--max-tokens`` controls generated output length. This resolver is for
    prompt/context length only: an explicit ``--max-prompt-tokens`` value wins;
    otherwise the engine uses the automatic memory-safe estimate.
    """
    if explicit_limit is not None and explicit_limit > 0:
        return int(explicit_limit)
    return int(auto_estimate or 0)

def annotate_e2e(obj, num_tasks, is_aggregate):
    """Recursively add "unnormalized_e2e" and "request/s" beside every "e2e_s".

    Descends through dicts and lists. Whenever a dict contains an "e2e_s" key
    with a numeric value, that value is first normalized (divided by
    num_tasks) if `is_aggregate` says the raw figure is actually a whole-run
    total rather than a per-request mean -- then the two companion keys are
    inserted using the (now per-request) value. Returns True if any change was
    made anywhere in `obj`.
    """
    changed = False
    if isinstance(obj, dict):
        if 'e2e_s' in obj:
            value = obj['e2e_s']
            if isinstance(value, (int, float)) and (not isinstance(value, bool)):
                if is_aggregate and num_tasks:
                    value = value / num_tasks
                    obj['e2e_s'] = value
                obj['unnormalized_e2e'] = value * num_tasks
                obj['request/s'] = 1.0 / value if value != 0 else None
                changed = True
        for child in obj.values():
            changed |= annotate_e2e(child, num_tasks, is_aggregate)
    elif isinstance(obj, list):
        for item in obj:
            changed |= annotate_e2e(item, num_tasks, is_aggregate)
    return changed

def GetHotkey(text):
    """Return the position and character of the hotkey"""
    curEnd = len(text) + 1
    text = text.replace('&&', '__')
    while True:
        pos = text.rfind('&', 0, curEnd)
        if pos in [-1, len(text)]:
            return (-1, '')
        if text[pos - 1] == '&':
            curEnd = pos - 2
            continue
        return (pos, text[pos + 1])

def release_agentic_ask(vault_path='wiki_vault', question='', max_tool_calls=5, dry_run=False, synthesize=True, protocol_mode=False):
    """Release compatible agentic ask.

    Handles older call sites where the CLI passed synthesize=...
    but the packaged function did not accept that keyword.
    """
    original_question = question
    question = release_repair_query_text(question) if 'release_repair_query_text' in globals() else str(question or '')
    state = {}
    trace = []
    evidence = []
    selected = release_agentic_select_tools(question) if 'release_agentic_select_tools' in globals() else ['wiki_search_with_notes', 'wiki_capabilities']
    if 'limitation' in question and 'wiki_limitations_report' not in selected:
        selected.insert(0, 'wiki_limitations_report')
    for tool in selected[:int(max_tool_calls)]:
        if 'release_execute_agent_tool_by_name' in globals():
            result = release_execute_agent_tool_by_name(vault_path, tool, {'query': question}, question, state)
        elif tool == 'wiki_search_with_notes' and 'release_search_with_notes' in globals():
            result = release_search_with_notes(vault_path, question, 8)
        elif tool == 'wiki_capabilities' and 'release_runtime_capabilities' in globals():
            result = release_runtime_capabilities(vault_path)
        elif tool == 'wiki_usage_snapshot' and 'release_wiki_usage_snapshot' in globals():
            result = release_wiki_usage_snapshot(vault_path)
        elif tool == 'wiki_self_access_snapshot' and 'release_self_access_snapshot' in globals():
            result = release_self_access_snapshot(vault_path)
        elif tool == 'wiki_limitations_report' and 'release_limitations_report' in globals():
            result = release_limitations_report(vault_path)
        else:
            result = {'ok': False, 'error': f'Tool unavailable: {tool}'}
        trace.append({'tool': tool, 'arguments': {'query': question}, 'result_type': type(result).__name__})
        evidence.append({'tool': tool, 'result': result})
        if tool == 'wiki_search_with_notes' and isinstance(result, dict) and result.get('results'):
            state['focus_page'] = result['results'][0].get('title')
    manifest = release_agentic_tool_manifest() if 'release_agentic_tool_manifest' in globals() else {}
    prompt_parts = ['# Agentic Ask Evidence Pack', f'Original question: {original_question}', f'Repaired question: {question}', '', '## Tool Manifest', _release_json.dumps(manifest, indent=2) if '_release_json' in globals() else str(manifest), '', '## Tool Trace', _release_json.dumps(trace, indent=2) if '_release_json' in globals() else str(trace), '', '## Evidence']
    for item in evidence:
        if '_release_json' in globals():
            prompt_parts.append('```json\n' + _release_json.dumps(item, indent=2, ensure_ascii=False)[:7000] + '\n```')
        else:
            prompt_parts.append(str(item)[:7000])
    prompt_parts.append("\n## Final Answer Instructions\n\nAnswer the user's question using the evidence above.\nPrefer current runtime/tool state over stale docs.\nMention the tools/pages used as evidence.\nIf evidence is missing, say what is missing and suggest the next safe tool to call.\n")
    prompt = '\n'.join(prompt_parts)
    if 'release_record_runtime_event' in globals():
        runtime_event = release_record_runtime_event(vault_path, 'ask-agentic', original_question, [t['tool'] for t in trace], True, None, {'prompt_tokens_estimate': release_estimate_tokens(prompt) if 'release_estimate_tokens' in globals() else len(prompt) // 4}, {'dry_run': dry_run, 'protocol_mode': protocol_mode, 'synthesize': synthesize})
    else:
        runtime_event = {}
    if dry_run or not synthesize:
        return {'ok': True, 'question': original_question, 'repaired_question': question, 'dry_run': True, 'tools_called': [t['tool'] for t in trace], 'trace': trace, 'evidence': evidence, 'llm_prompt': prompt, 'runtime_event': runtime_event, 'answer': None}
    if 'release_ollama_generate' in globals():
        llm = release_ollama_generate(vault_path, prompt)
        answer = llm.get('answer') if llm.get('ok') else f"Agentic evidence was built, but Ollama synthesis failed: {llm.get('error')}"
    else:
        llm = {'ok': False, 'error': 'release_ollama_generate is not available'}
        answer = 'Agentic evidence was built, but Ollama synthesis is not available in this package.'
    if 'release_record_ask_turn_with_metrics' in globals():
        metrics = release_record_ask_turn_with_metrics(vault_path, original_question, prompt, answer, [e.get('tool') for e in evidence], llm.get('elapsed_seconds'), {'agentic': True, 'protocol_mode': protocol_mode, 'ollama': llm})
    else:
        metrics = {}
    return {'ok': bool(llm.get('ok')), 'question': original_question, 'repaired_question': question, 'answer': answer, 'tools_called': [t['tool'] for t in trace], 'trace': trace, 'evidence': evidence, 'llm': llm, 'metrics': metrics, 'runtime_event': runtime_event, 'llm_prompt': prompt}

def get_status_code(status, short=False):
