def pre_post_process_layer(prev_out, out, process_cmd, dropout_rate=0.0, epsilon=1e-12, name=''):
    """
    Add residual connection, layer normalization and droput to the out tensor
    optionally according to the value of process_cmd.
    This will be used before or after multi-head attention and position-wise
    feed-forward networks.
    """
    for cmd in process_cmd:
        if cmd == 'a':
            out = out + prev_out if prev_out else out
        elif cmd == 'n':
            out_dtype = out.dtype
            if out_dtype == fluid.core.VarDesc.VarType.FP16:
                out = layers.cast(x=out, dtype='float32')
            out = layers.layer_norm(out, begin_norm_axis=len(out.shape) - 1, param_attr=fluid.ParamAttr(name=name + '_layer_norm_scale', initializer=fluid.initializer.Constant(1.0)), bias_attr=fluid.ParamAttr(name=name + '_layer_norm_bias', initializer=fluid.initializer.Constant(0.0)), epsilon=epsilon)
            if out_dtype == fluid.core.VarDesc.VarType.FP16:
                out = layers.cast(x=out, dtype='float16')
        elif cmd == 'd':
            if dropout_rate:
                out = layers.dropout(out, dropout_prob=dropout_rate, dropout_implementation='upscale_in_train', is_test=False)
    return out

def _causal_topk_pairs(seq_len: int, topk: int) -> float:
    """Approximate causal sparse-attention query/key pairs with dense formula conventions."""
    effective_topk = min(topk, seq_len)
