def inverse_data_size(value, include_space=True):
    """
    Invert the data_size() function to convert a size in bytes into a
    data size string.
    """
    if value >= 1024 ** 4:
        string = f'{value / 1024 ** 4:.1f} TiB'
    elif value >= 1024 ** 3:
        string = f'{value / 1024 ** 3:.1f} GiB'
    elif value >= 1024 ** 2:
        string = f'{value / 1024 ** 2:.1f} MiB'
    elif value >= 1024:
        string = f'{value / 1024:.1f} kiB'
    else:
        string = f'{value:.1f} B'
    if not include_space:
        string = string.replace(' ', '')
    return string

def poly_mult_2(a: int, b: int):
    """
    Return binary multplication in Z2
    """

    def multbiggest(a, b):
        r = 0
        for i in range(a.bit_length()):
            if a >> i & 1:
                r ^= b << i
        return r
    if a.bit_length() >= b.bit_length():
        return multbiggest(a, b)
    return multbiggest(b, a)

def classify_mechanism(col: str, mask: list[bool], all_masks: dict[str, list[bool]]) -> str:
    """
    Heuristic classification of missingness mechanism:
    - MCAR: nulls appear randomly, no correlation with other columns
    - MAR:  nulls correlate with values in other observed columns
    - MNAR: nulls correlate with the missing column's own unobserved value (can't fully detect)

    Returns one of: "MCAR (likely)", "MAR (likely)", "MNAR (possible)", "Insufficient data"
    """
    null_indices = {i for (i, v) in enumerate(mask) if v}
    if not null_indices:
        return 'None'
    n = len(mask)
    if n < 10:
        return 'Insufficient data'
    correlated_cols = []
    for (other_col, other_mask) in all_masks.items():
        if other_col == col:
            continue
        other_null_indices = {i for (i, v) in enumerate(other_mask) if v}
        if not other_null_indices:
            continue
        overlap = len(null_indices & other_null_indices)
        union = len(null_indices | other_null_indices)
        jaccard = overlap / union if union else 0
        if jaccard > 0.5:
            correlated_cols.append(other_col)
    sorted_indices = sorted(null_indices)
    if len(sorted_indices) > 2:
        gaps = [sorted_indices[i + 1] - sorted_indices[i] for i in range(len(sorted_indices) - 1)]
        avg_gap = sum(gaps) / len(gaps)
        clustered = avg_gap < n / len(null_indices) * 0.5
    else:
        clustered = False
    if correlated_cols:
        return f"MAR (likely) — co-occurs with nulls in: {', '.join(correlated_cols[:3])}"
    elif clustered:
        return 'MNAR (possible) — nulls are spatially clustered, may reflect a systematic gap'
    else:
        return 'MCAR (likely) — nulls appear random, no strong correlation detected'

def _is_single_value(value):
    """
    Check if a value is a single numeric value or a single character.

    Parameters:
    -----------
        value (int, float, str): The value to be checked.

    Returns:
    --------
        bool: True if the value is a single numeric value or a single character, False otherwise.
    """
    if isinstance(value, (int, float, str)):
        if isinstance(value, (int, float)):
            return True
        elif isinstance(value, str):
            if len(value) == 1 and value.isdigit():
                return True
            else:
                return False
    return False

def _extract_preferred_field(data, id_or_value):
    """In case the preferred representation of data when the latter has multiple representations"""
    if not id_or_value:
        return data
    if not data:
        return ''
    if isinstance(data, dict):
        if id_or_value in data:
            return data[id_or_value]
    if isinstance(data, list):
        return ','.join([_extract_preferred_field(i, id_or_value) for i in data])
    return data

def _parse_pos(raw):
    """Normalize a FlowView position return into (x, y) floats, or None.

    Depending on the bridge, position reads come back as a 1-indexed Lua table,
    a dict ({1: x, 2: y} / {"x": .., "y": ..}), or an (x, y) tuple/list. Be
    liberal in what we accept.
    """
    if raw is None:
        return None
    if isinstance(raw, dict):
        for (ka, kb) in ((1, 2), ('1', '2'), ('x', 'y'), ('X', 'Y')):
            if ka in raw and kb in raw:
                try:
                    return (float(raw[ka]), float(raw[kb]))
                except (TypeError, ValueError):
                    return None
        vals = list(raw.values())
        if len(vals) >= 2:
            try:
                return (float(vals[0]), float(vals[1]))
            except (TypeError, ValueError):
                return None
        return None
    if isinstance(raw, (list, tuple)):
        if len(raw) >= 2:
            try:
                return (float(raw[0]), float(raw[1]))
            except (TypeError, ValueError):
                return None
        return None
    try:
        return (float(raw[1]), float(raw[2]))
    except Exception:
        return None

def _extract_c_block(text: str, opening_brace: int) -> str | None:
    """Return a balanced C block, including its braces."""
    if opening_brace >= len(text) or text[opening_brace] != '{':
        return None
    depth = 0
    for index in range(opening_brace, len(text)):
        char = text[index]
        if char == '{':
            depth += 1
        elif char == '}':
            depth -= 1
            if depth == 0:
                return text[opening_brace:index + 1]
    return None

def resolve(d):
    """Collapse a dimensionWithTolerance to a scalar: nominal -> mid -> max -> min.

    Mirrors MKF's resolve_dimensional_values. Returns None when the value carries no
    bound at all; callers treat that as 'not specified', never as zero.
    """
    if isinstance(d, bool):
        return None
    if isinstance(d, (int, float)):
        return float(d)
    if not isinstance(d, dict):
        return None
    if d.get('nominal') is not None:
        return float(d['nominal'])
    (mn, mx) = (d.get('minimum'), d.get('maximum'))
    if mn is not None and mx is not None:
        return (float(mn) + float(mx)) / 2.0
    if mx is not None:
        return float(mx)
    if mn is not None:
        return float(mn)
    return None

def _compute_dfd_type_layers(scope_data):
    """Fallback layer derivation: group Section 1 components by DFD type when no trust zones exist."""
    components = scope_data.get('components', [])
    if not components:
        return None
    by_type = {}
    for comp in components:
        ctype = (comp.get('type') or '').strip()
        cname = (comp.get('name') or '').strip()
        if not ctype or not cname:
            continue
        by_type.setdefault(ctype, []).append(cname)
    if not by_type:
        return None
    layers = []
    for (position, ctype) in enumerate(sorted(by_type.keys())):
        comp_names = sorted(by_type[ctype])
        if not comp_names:
            continue
        layers.append({'name': ctype, 'position': position, 'components': comp_names, 'component_count': len(comp_names), 'source_kind': 'dfd_type'})
    return layers if layers else None

@staticmethod
def _ramp(val: float, pos_key: bool, neg_key: bool, inc: float, upper: float, lower: float=None) -> float:
    """Bidirectional ramp with upper/lower bounds. Holds current value when keys released."""
    if lower is None:
        lower = -upper
    if pos_key and (not neg_key):
        return min(upper, val + inc)
    if neg_key and (not pos_key):
        return max(lower, val - inc)
    return val

def remove_empty_track(midi_file):
    """
    1. read pretty midi data
    2. remove emtpy track,
    also remove track with fewer than 10% notes of the track
    with most notes

    ********
    Return: pretty_midi object, pypianoroll object
    """
    try:
        pretty_midi_data = pretty_midi.PrettyMIDI(midi_file)
    except Exception as e:
        print(f'exceptions in read the file {midi_file}')
        return (None, None)
    pypiano_data = pypianoroll.Multitrack()
    try:
        pypiano_data.parse_pretty_midi(pretty_midi_data, skip_empty_tracks=False)
    except Exception as e:
        print(f'exceptions for pypianoroll in read the file {midi_file}')
        return (None, None)
    drum_idx = []
    for (i, instrument) in enumerate(pretty_midi_data.instruments):
        if instrument.is_drum:
            drum_idx.append(i)
    note_count = [np.count_nonzero(np.any(track.pianoroll, axis=1)) for track in pypiano_data.tracks]
    empty_indices = np.array(note_count) < 10
    remove_indices = np.arange(len(pypiano_data.tracks))[empty_indices]
    for index in sorted(remove_indices, reverse=True):
        del pypiano_data.tracks[index]
        del pretty_midi_data.instruments[index]
    return (pretty_midi_data, pypiano_data)

def _platform_supported(mod) -> bool:
    """True if *mod* declares no PLATFORMS attribute, or the current
    ``sys.platform`` matches one of its declared prefixes. Lets a
    scenario opt out of OSes where its connect path doesn't apply
    (e.g. bl_connect_local on macOS/Windows, bl_connect_win_native on
    Linux/macOS)."""
    plats = getattr(mod, 'PLATFORMS', None)
    if plats is None:
        return True
    return any((sys.platform.startswith(p) for p in plats))

def _find_integration(skill: dict, integration_id: str) -> dict | None:
    """Return the integrations[] entry with id == integration_id, or None."""
    for i in skill.get('integrations') or []:
        if i.get('id') == integration_id:
            return i
    return None

def extract_vulns_for_file(results, target_file):
    """Extract list of (cvi_id, lineno, is_inconclusive) from scan results for a specific file."""
    if not results:
        return []
    vulns = []
    items = []
    if isinstance(results, list):
        items = results
    elif isinstance(results, dict):
        for key in ('results', 'vulnerabilities', 'data'):
            if key in results and isinstance(results[key], list):
                items = results[key]
                break
    for item in items:
        if not isinstance(item, dict):
            continue
        file_val = item.get('file') or item.get('file_path') or item.get('file_name') or ''
        if target_file in file_val:
            cvi = item.get('cvi_id') or item.get('cvi') or item.get('vuln_class') or ''
            cvi_str = str(cvi)
            if cvi_str.isdigit():
                cvi_str = 'CVI-' + cvi_str
            lineno = None
            if ':' in str(file_val):
                parts = str(file_val).rsplit(':', 1)
                if parts[-1].isdigit():
                    lineno = int(parts[-1])
            result_type = item.get('result_type') or item.get('type') or ''
            is_inconclusive = 'Inconclusive' in str(result_type)
            if 'CVI' in cvi_str:
                vulns.append((cvi_str, lineno, is_inconclusive))
    return vulns

@staticmethod
def strip_textpad(text):
    """
        Attempt to intelligently strip excess whitespace from the output of a
        curses textpad.
        """
    if text is None:
        return text
    if '\n' not in text:
        return text.rstrip()
    (stack, current_line) = ([], '')
    for line in text.split('\n'):
        if line.endswith('  ') or not line:
            stack.append(current_line + line.rstrip())
            current_line = ''
        else:
            current_line += line
    stack.append(current_line)
    for item in stack[::-1]:
        if not item:
            stack.pop()
        else:
            break
    out = '\n'.join(stack)
    return out

def get_test_id(data):
    """
    Method to retrieve test_id
    :param data:
    :return:
    """
    test_id = ''
    if 'rule_set' in data:
        test_id = data['rule_set']
    if 'test_id' in data:
        test_id = data['test_id']
    if 'rule_id' in data:
        test_id = data['rule_id']
    if 'check_name' in data:
        test_id = data['check_name']
    if 'check_id' in data:
        test_id = data['check_id']
    if 'tag' in data:
        test_id = data['tag']
    if 'commitMessage' in data and 'commit' in data:
        test_id = 'CWE-312'
    if 'type' in data:
        test_id = data['type']
    if 'cwe' in data:
        cwe_obj = data['cwe']
        if isinstance(cwe_obj, str):
            test_id = cwe_obj
        if isinstance(cwe_obj, dict):
            tmp_id = cwe_obj.get('ID')
            if not tmp_id:
                tmp_id = cwe_obj.get('id')
            if tmp_id:
                test_id = tmp_id
        if not test_id.startswith('CWE') and test_id.isdigit():
            test_id = 'CWE-' + test_id
    if not test_id and 'code' in data and data.get('code'):
        if str(data.get('code')).isdigit():
            test_id = str(data['code'])
        elif len(data.get('code').split()) == 1:
            test_id = data.get('code')
    return test_id

def is_true(value=None):
    """
    Returns a boolean value representing the "truth" of the value passed. The
    rules for what is a "True" value are:

        1. Integer/float values greater than 0
        2. The string values "True" and "true"
        3. Any object for which bool(obj) returns True
    """
    try:
        value = int(value)
    except (ValueError, TypeError):
        pass
    try:
        value = float(value)
    except (ValueError, TypeError):
        pass
    if isinstance(value, (int, float)):
        return value > 0
    elif isinstance(value, str):
        return str(value).lower() == 'true'
    else:
        return bool(value)

def config_positive_float_value(value):
    """
    Returns positive float value if it can be cast by float() and it's a
    float > 0. (not including zero) Raises ValueError otherwise.
    """
    try:
        result = float(value)
        if result <= 0:
            raise ValueError()
    except (TypeError, ValueError):
        raise ValueError('Config option must be a positive float number, not "%s".' % value)
    return result

def _format_tokens(input_tokens: int, output_tokens: int) -> str:
    """Humanise token counts as '1.2M tokens (↑890K / ↓355K)'. Returns '' when both are zero."""
    total = input_tokens + output_tokens
    if total == 0:
        return ''

    def _fmt(n: int) -> str:
        if n >= 1000000:
            return f'{n / 1000000:.1f}M'
        if n >= 1000:
            return f'{n / 1000:.0f}K'
        return str(n)
    return f'{_fmt(total)} tokens (↑{_fmt(input_tokens)} / ↓{_fmt(output_tokens)})'

def count_ast(ast):
    """Walk the pandoc AST. Return (real_cite_groups, images, tables, math).
    real_cite_groups = number of Cite nodes containing >=1 real citekey (each becomes ONE Zotero
    field downstream, mirroring zotero_offline.lua's one-field-per-Cite behaviour)."""
    cnt = {'cite': 0, 'image': 0, 'table': 0, 'math': 0}

    def walk(x):
        if isinstance(x, dict):
            t = x.get('t')
            if t == 'Cite':
                ids = [c.get('citationId') for c in x['c'][0]]
                if any((_is_real_key(i) for i in ids)):
                    cnt['cite'] += 1
            elif t == 'Image':
                cnt['image'] += 1
            elif t == 'Table':
                cnt['table'] += 1
            elif t == 'Math':
                cnt['math'] += 1
            for v in x.values():
                walk(v)
        elif isinstance(x, list):
            for v in x:
                walk(v)
    walk(ast)
    return (cnt['cite'], cnt['image'], cnt['table'], cnt['math'])

def _matches(url: str, filters: list[str]) -> bool:
    """Return True if url contains at least one of the filter substrings (or no filters set)."""
    if not filters:
        return True
    return any((f in url for f in filters))

@staticmethod
def _get_mode_parameters(mode):
    """ Return the correst TraCI parameters for the requested mode.
            Parameters: _mode, _ptype, _vtype
        """
    if mode == 'public':
        return ('public', '', '')
    if mode == 'bicycle':
        return ('bicycle', '', 'bicycle')
    if mode == 'walk':
        return ('', 'pedestrian', '')
    return ('car', '', mode)

def index_dispatch_edges(path):
    """Return host-op -> dispatched GPU kernels using profiler External ids.

    TraceLens may report one aggregate host/custom-op row whose percentage is the sum of several
    kernels.  Such a row is useful context but it is not a kernel-selection candidate.  This index
    provides the machine-observed children needed to split it before strategizing.
    """
    try:
        with _open(path) as fh:
            data = json.load(fh)
    except Exception:
        return {}
    events = data.get('traceEvents', data if isinstance(data, list) else [])
    host_by_ext = {}
    spans_by_thread = {}
    for event in events:
        if not isinstance(event, dict) or event.get('cat') not in ('cpu_op', 'user_annotation'):
            continue
        ext = (event.get('args') or {}).get('External id')
        if ext is not None:
            host_by_ext.setdefault(ext, set()).add(event.get('name', '?'))
        if ext is not None and event.get('ts') is not None:
            start = float(event['ts'])
            end = start + float(event.get('dur') or 0.0)
            spans_by_thread.setdefault((event.get('pid'), event.get('tid')), []).append((start, end, event.get('name', '?'), ext))
    for spans in spans_by_thread.values():
        stack = []
        for (start, end, name, ext) in sorted(spans, key=lambda item: (item[0], -item[1])):
            while stack and stack[-1][0] <= start:
                stack.pop()
            names = host_by_ext.setdefault(ext, set())
            names.add(name)
            names.update((parent_name for (_, parent_name) in stack))
            stack.append((end, name))
    edges = {}
    for event in events:
        if not isinstance(event, dict) or event.get('cat') != 'kernel':
            continue
        ext = (event.get('args') or {}).get('External id')
        hosts = host_by_ext.get(ext) or ()
        for host in hosts:
            child = edges.setdefault(host, {}).setdefault(event.get('name', '?'), {'calls': 0, 'total_us': 0.0})
            child['calls'] += 1
            child['total_us'] += float(event.get('dur') or 0.0)
    return edges

def process_record(record: dict) -> tuple[dict, bool, str | None]:
    """
    Process a single training record, canonicalizing the CXSMILES if present.

    Args:
        record: Training record dict with 'messages' list

    Returns:
        Tuple of (processed_record, was_changed, error_message)
    """
    for msg in record.get('messages', []):
        if msg.get('role') == 'assistant':
            content = msg.get('content', '')
            cxsmiles = extract_cxsmiles_from_content(content)
            if cxsmiles is None:
                return (record, False, 'no_cxsmiles')
            result = canonicalize_cxsmiles_checked(cxsmiles)
            if result.value is None:
                return (record, False, result.error or f'parse_failed: {cxsmiles[:100]}')
            if result.fallback:
                return (record, False, f'verify_failed: {result.error}')
            canonical = result.value
            if cxsmiles == canonical:
                return (record, False, None)
            new_content = replace_cxsmiles_in_content(content, canonical)
            msg['content'] = new_content
            return (record, True, None)
    return (record, False, 'no_assistant_message')

def _get_dimension_criteria(dimension: str) -> list[str]:
    """
    Get expected criteria names for a dimension.

    Args:
        dimension: Dimension name

    Returns:
        List of criterion names
    """
    criteria_map = {'completeness': ['has_all_required_steps', 'addresses_all_query_aspects', 'handles_edge_cases', 'includes_fallback_path'], 'efficiency': ['minimizes_redundant_calls', 'uses_appropriate_agents', 'optimizes_cost', 'optimizes_latency'], 'safety': ['validates_inputs', 'handles_errors_gracefully', 'has_timeout_protection', 'avoids_risky_combinations'], 'coherence': ['logical_agent_sequence', 'proper_data_flow', 'no_conflicting_actions']}
    return criteria_map.get(dimension, [])

def normalize_arxiv_id(value: str) -> str:
    """
    统一将可能携带 URL 的 arXiv 输入转换为 id。
    兼容：
    - 1706.03762
    - 1706.03762v1
    - https://arxiv.org/abs/1706.03762v1
    """
    raw = (value or '').strip()
    if not raw:
        return ''
    if raw.startswith('http://') or raw.startswith('https://'):
        raw = raw.rsplit('/', 1)[-1]
    raw = raw.split('?')[0]
    if raw.startswith('abs/'):
        raw = raw[len('abs/'):]
    if raw.startswith('pdf/'):
        raw = raw[len('pdf/'):].replace('.pdf', '')
    return raw.strip().lower()

def inspect_jwt_bfs(token: str) -> dict:
    """Detect xAI JWT risk claim ``bfs`` by key presence (not truthiness).

    Clean tokens simply omit the claim. Flagged tokens typically carry
    ``bfs: 2`` (value may vary; presence alone is the signal).
    Distinct from grok.com ``botFlagSource`` / registration policy deny.
    """
    raw = str(token or '').strip()
    if raw.startswith('sso='):
        raw = raw[4:].strip()
    if raw.startswith('{'):
        try:
            obj = json.loads(raw)
        except Exception:
            obj = None
        if isinstance(obj, dict):
            for key in ('access_token', 'token', 'sso', 'id_token', 'key'):
                nested = str(obj.get(key) or '').strip()
                if nested.count('.') >= 2:
                    raw = nested
                    break
    (ok, claims) = _decode_jwt_payload_with_status(raw) if raw.count('.') >= 2 else (False, {})
    has = ok and 'bfs' in claims
    return {'ok': ok, 'has_bfs': has, 'bfs': claims.get('bfs') if has else None, 'tier': claims.get('tier'), 'sub': str(claims.get('sub') or claims.get('principal_id') or '')[:48], 'exp': claims.get('exp'), 'referrer': claims.get('referrer'), 'claim_keys': sorted((str(k) for k in claims.keys())) if claims else []}

def bytes_to_str(value):
    """Covert an integer (in bytes) into it's string representation with
    acompanied unit value (such as B, KB, MB, GB, TB, etc)"""
    unit = 'B'
    try:
        value = float(value)
    except (ValueError, TypeError):
        return None
    if value >= 1024.0:
        value = value / 1024.0
        unit = 'KB'
        if value >= 1024.0:
            value = value / 1024.0
            unit = 'MB'
            if value >= 1024.0:
                value = value / 1024.0
                unit = 'GB'
                if value >= 1024.0:
                    value = value / 1024.0
                    unit = 'TB'
    return f'{round(value, 2):.2f}{unit}'

def validate_ms(value: int | str) -> str:
    """
    Normalize milliseconds value for config storage.
    Always stored as '<int>ms', non-negative.
    """
    if isinstance(value, int):
        if value < 0:
            raise ValueError('Milliseconds must be non-negative.')
        return f'{value}ms'
    if isinstance(value, str):
        v = value.strip().lower().replace(' ', '')
        if v.endswith('ms'):
            v = v[:-2]
        try:
            n = int(v)
        except ValueError as e:
            raise ValueError(f'Invalid millisecond value: {value!r}') from e
        if n < 0:
            raise ValueError('Milliseconds value must be non-negative.')
        return f'{n}ms'
    raise ValueError(f"Invalid millisecond value: '{value}'")

def get_lr_trapezoidal(step, num_step, warmup_iters=256, cooldown_frac=0.4):
    """Trapezoidal schedule from modded-nanogpt 844e5fd.

    Linear warmup, constant plateau, then linear warmdown to zero.
    Returns a multiplier in [0, 1] applied to the base learning rate.
    """
    if step < warmup_iters:
        return (step + 1) / warmup_iters
    return get_lr(step, num_step, cooldown_frac)

def merge_categories(cat_sets: set, fallback: str) -> str:
    """Collapse a set of "a,b" category strings into one sorted, de-duped
    comma list. Falls back to `fallback` when nothing was mapped."""
    ids = set()
    for c in cat_sets:
        for part in c.split(','):
            part = part.strip()
            if part.isdigit():
                ids.add(int(part))
    if not ids:
        for part in fallback.split(','):
            part = part.strip()
            if part.isdigit():
                ids.add(int(part))
    return ','.join((str(i) for i in sorted(ids))) or '15'

def _convert_weight_key(key: str, model: 'PreTrainedModel') -> str:
    """
    Convert a single state dict key using the model's checkpoint conversion mapping.

    For example, in the InternVL, we have _checkpoint_conversion_mapping = {"^model": "language_model"}

    This is to adapt to the big breaking change introduced in HF transformers 4.52:
    https://github.com/huggingface/transformers/pull/38385
    """
    if not hasattr(model, '_checkpoint_conversion_mapping'):
        return key
    for (pattern, replacement) in model._checkpoint_conversion_mapping.items():
        replacement = replacement.lstrip('^')
        replacement = re.sub('\\(.*\\)', '', replacement)
        (converted_key, n_replace) = re.subn(pattern, replacement, key)
        if n_replace > 0:
            return converted_key
    return key

def _product_byte_size(props: dict) -> int | None:
    """Byte size of the main product file (the one ``download()`` fetches).

    S1/ALOS expose ``bytes`` as an int. NISAR exposes a dict mapping every file
    in the granule to ``{'bytes': N, 'format': ...}``; return the entry for the
    file we actually download (``fileName`` == the ``url`` basename), falling
    back to the sum of all entries.
    """
    raw = props.get('bytes')
    if isinstance(raw, bool):
        return None
    if isinstance(raw, (int, float)):
        return int(raw)
    if isinstance(raw, dict):
        filename = props.get('fileName')
        if filename:
            entry = raw.get(filename)
            if isinstance(entry, dict) and isinstance(entry.get('bytes'), (int, float)):
                return int(entry['bytes'])
        total = 0
        for v in raw.values():
            if isinstance(v, dict) and isinstance(v.get('bytes'), (int, float)):
                total += int(v['bytes'])
        return total or None
    return None

def _prune_none_for_apigw_json(obj):
    """Drop None members so the wire never emits JSON `null` (real AWS typically omits optional nulls;
    boto3 then maps the same shape for clients as AWS). Recurses into dict values."""
    if isinstance(obj, dict):
        return {k: _prune_none_for_apigw_json(v) for (k, v) in obj.items() if v is not None}
    if isinstance(obj, list):
        return [_prune_none_for_apigw_json(x) for x in obj]
    return obj

@staticmethod
def _bisect_left(a, x, lo=0, key=None):
    """Polyfill for bisect.bisect_left with key argument
    TODO: replace with standard library version when Python 3.10+ is minimum requirement
    """
    if lo < 0:
        raise ValueError('lo must be non-negative')
    hi = len(a)
    if key is None:
        key = lambda v: v
    while lo < hi:
        mid = (lo + hi) // 2
        v = key(a[mid])
        if v is not None and v < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

