@staticmethod
def _merge_a_into_b(a, b):
    """merge dict `a` into dict `b` (non-inplace).
            values in `a` will overwrite `b`.
            copy first to avoid inplace modification

        Args:
            a ([type]): [description]
            b ([type]): [description]

        Returns:
            [dict]: [description]
        """
    if not isinstance(a, dict):
        return a
    b = b.copy()
    for (k, v) in a.items():
        if isinstance(v, dict) and k in b and (not v.pop(DELETE_KEY, False)):
            if not isinstance(b[k], dict) and (not isinstance(b[k], list)):
                raise TypeError(f'{k}={v} in child config cannot inherit from base because {k} is a dict in the child config but is of type {type(b[k])} in base config. You may set `{DELETE_KEY}=True` to ignore the base config')
            b[k] = Config._merge_a_into_b(v, b[k])
        elif isinstance(b, list):
            try:
                _ = int(k)
            except:
                raise TypeError(f'b is a list, index {k} should be an int when input but {type(k)}')
            b[int(k)] = Config._merge_a_into_b(v, b[int(k)])
        else:
            b[k] = v
    return b

def is_prime(number: int) -> bool:
    """
    Check if a number is prime.

    :param number: The number to check.
    :return: True if the number is prime, False otherwise.
    """
    if number <= 1:
        return False
    for i in range(2, int(number ** 0.5) + 1):
        if number % i == 0:
            return False
    return True

