def generate_typescript_interface(name: str='TestInterface', properties: dict[str, str] | None=None, methods: dict[str, str] | None=None) -> str:
    """
    Generate TypeScript interface code.

    Args:
        name: Interface name
        properties: Dictionary of property name to type
        methods: Dictionary of method name to signature

    Returns:
        TypeScript interface code as string
    """
    if properties is None:
        properties = {}
    if methods is None:
        methods = {}
    lines = [f'interface {name} {{']
    for (prop, type_str) in properties.items():
        lines.append(f'  {prop}: {type_str};')
    for (method, signature) in methods.items():
        lines.append(f'  {method}{signature};')
    lines.append('}')
    return '\n'.join(lines)

def _entity_attr_names(table_def: dict) -> dict:
    """{entity_name: set(attribute names)} for one table.

    A DynamoDB item only appears in (and only amplifies a write to) a GSI whose
    key attributes it actually CARRIES. In a single-table design with
    heterogeneous entities, each GSI is keyed on an attribute only some entities
    have — so this per-entity attribute-name set is what decides GSI membership.
    """
    out = {}
    for ent in table_def.get('entities', []) or []:
        name = ent.get('entity_name')
        if not name:
            continue
        out[name] = {a['name'] for a in ent.get('attributes', []) or [] if a.get('name')}
    return out

