    sys : I/O system, optional
        System to be checked.
    dt : None or number, optional
        Timebase to be checked.
    strict : bool (default = False)
        If strict is True, make sure that timebase is not None.
    """
    if sys is None:
        if dt is None:
            return True if not strict else False
        else:
            return dt == 0
    elif dt is not None:
        raise TypeError('passing both system and timebase not allowed')
    if isinstance(sys, (int, float, complex, np.number)):
        return True if not strict else False
    else:
        return sys.isctime(strict)

@staticmethod
def isCached(cache, key):
    """Returns whether a given function has been cached already.

        Mocked in tests to disable caching as needed."""
    if key in cache:
        return True
    return False

def _wrap_js_for_evaluate(script: str, n_args: int) -> tuple[str, list]:
    """把 DrissionPage 的 run_js(script, *args) 包装成 Playwright evaluate 格式。

    DrissionPage: page.run_js("return arguments[0] + 1", 5)
    Playwright:   page.evaluate("(a) => { return a + 1; }", 5)

    策略：
    1. 把 arguments[0], arguments[1]... 替换为参数名 __cf_a0, __cf_a1...
    2. 用箭头函数包装，无参数时用 IIFE
    """
    script = script.strip()
    if n_args == 0:
        wrapped = f'(() => {{ {script} }})()'
        return (wrapped, [])
    param_names = []
    modified = script
    for i in range(n_args):
        pname = f'__cf_a{i}'
        modified = modified.replace(f'arguments[{i}]', pname)
        param_names.append(pname)
    if n_args == 1:
        wrapped = f'({param_names[0]}) => {{ {modified} }}'
        return (wrapped, [])
    else:
        params = ', '.join(param_names)
        wrapped = f'([{params}]) => {{ {modified} }}'
        return (wrapped, list(range(n_args)))

def _is_freq_func(x):
    """Whether a frequency specification (Omega or Omegadot) is given as
    function(s) of time rather than constant(s): a callable, or a sequence whose
    first element is callable."""
    if callable(x):
        return True
    try:
        return callable(x[0])
    except (TypeError, IndexError, KeyError):
        return False

def strip_quotes(s, qchar='"'):
    """Return string s with any enclosing quotes removed.
    They are only removed if both are present."""
    if len(s) > 1:
        if s[0] == qchar and s[-1] == qchar:
            s = s[1:-1]
    return s

def _is_retryable(exc: Exception) -> bool:
    """Return True if an exception looks transient."""
    if isinstance(exc, (TimeoutError, ConnectionError)):
        return True
    exc_module = type(exc).__module__
    exc_name = type(exc).__name__
    if exc_module == 'httpx' and exc_name in ('ConnectError', 'ReadError', 'WriteError', 'TimeoutException', 'NetworkError'):
        return True
    return exc_module == 'openai' and exc_name in ('RateLimitError', 'InternalServerError', 'APITimeoutError', 'APIConnectionError')

def _nvidia_uuid_idx():
    """GPU UUID → card index. --query-compute-apps identifies a process's card by
    UUID, never by index, so this is the only way to answer "which card is this
    process on". {} when unavailable — attribution then stays card-agnostic."""
    out = {}
    try:
        for p in _smi_rows('index,uuid'):
            if len(p) >= 2 and p[1]:
                out[p[1]] = _smi_int(p[0])
    except Exception:
        pass
    return out

def _apk_installs_python3(dockerfile: str) -> bool:
    """Return True if python3 is an actual `apk add` package, not just text.

    Joins backslash-continued lines so a multi-line `apk add ... \\ python3`
    counts, but a bare comment mentioning python3 does not.
    """
    joined = dockerfile.replace('\\\n', ' ')
    for line in joined.splitlines():
        stripped = line.strip()
        if stripped.startswith('#'):
            continue
        if 'apk add' in stripped and 'python3' in stripped.split('apk add', 1)[1]:
            return True
    return False

def FormCATSLabel(PathLength=10):
    """
    #################################################################
    Construct the CATS label such as AA0, AA1,....AP3,.......

    The result is a list format.

    A   acceptor;
    P   positive;
    N   negative;
    L   lipophilic;
    D   donor;
    #################################################################
    """
    AtomPair = ['DD', 'DA', 'DP', 'DN', 'DL', 'AA', 'AP', 'AN', 'AL', 'PP', 'PN', 'PL', 'NN', 'NL', 'LL']
    CATSLabel = []
    for i in AtomPair:
        for k in range(PathLength):
            CATSLabel.append('CATS_' + i + str(k))
    return CATSLabel

def rdf2list(predicates):
    """Convert a nested RDF list to a simple list of objects.
    From
        {'rdf:type': [{'object': 'rdf:List'}],
         'rdf:first': [{'value': 'A'}],
         'rdf:rest': [{
             'object': {
                 'rdf:type': [{'object': 'rdf:List'}],
                 'rdf:first': [{'value': 'B'}],
                 'rdf:rest': [{'object': 'rdf:nil'}]}}]}}
    to
        [{"value": "A"}, {"value": "B"}]
    """
    result = []
    if 'rdf:first' in predicates:
        result.append(predicates['rdf:first'][0])
    if 'rdf:rest' in predicates:
        o = predicates['rdf:rest'][0]
        if not o:
            return result
        if not o.get('object'):
            return result
        if o['object'] == 'rdf:nil':
            return result
        return result + rdf2list(o['object'])
    return result

def markdown_adjust(text: str, window_start: int, split_at: int) -> int:
    """Move a split left when it cuts a Markdown or Chat link.

    Protected forms are ``[label](url)``, ``![alt](url)``, and
    ``<url|label>``. The scan looks backward for an opener and at most one
    window forward for its closer, keeping adjustment work linear.

    Returns the original split or the construct's opening position.
    """
    if split_at <= window_start or split_at > len(text):
        return split_at
    search_start = window_start
    forward_end = min(len(text), split_at + (split_at - window_start) + 1)
    link_start_idx = text.rfind('[', search_start, split_at)
    if link_start_idx == -1:
        bang = text.rfind('!', search_start, split_at)
        if bang != -1 and bang + 1 < len(text) and (text[bang + 1] == '['):
            link_start_idx = bang
    if link_start_idx != -1:
        link_end_idx = text.find(')', link_start_idx, forward_end)
        if link_end_idx != -1 and link_start_idx < split_at < link_end_idx:
            return link_start_idx
    angle_start_idx = text.rfind('<', search_start, split_at)
    if angle_start_idx != -1:
        pipe_idx = text.find('|', angle_start_idx + 1, forward_end)
        if pipe_idx != -1:
            angle_end_idx = text.find('>', pipe_idx, forward_end)
            if angle_end_idx != -1 and angle_start_idx < split_at <= angle_end_idx:
                return angle_start_idx
    return split_at

def _cpp_integer_type_for_range(min_val, max_val):
    """Returns the appropriate C++ integer type to hold min_val up to max_val."""
    for size in (32, 64):
        if min_val >= -2 ** (size - 1) and max_val <= 2 ** (size - 1) - 1:
            return '::std::int{}_t'.format(size)
        elif min_val >= 0 and max_val <= 2 ** size - 1:
            return '::std::uint{}_t'.format(size)
    return None

def _expand_with_neighbors(drawers_col, matched_doc: str, matched_meta: dict, radius: int=1):
    """Expand a matched drawer with its ±radius sibling chunks in the same source file.

    Motivation — "drawer-grep context" feature: a closet hit returns one
    drawer, but the chunk boundary may clip mid-thought (e.g., the matched
    chunk says "here's a breakdown:" and the actual breakdown lives in the
    next chunk). Fetching the small neighborhood around the match gives
    callers enough context without forcing a follow-up ``get_drawer`` call.

    Returns a dict with:
        ``text``            combined chunks in chunk_index order
        ``drawer_index``    the matched chunk's index in the source file
        ``total_drawers``   total drawer count for the source file (or None)

    On any ChromaDB failure or missing metadata, falls back to returning the
    matched drawer alone so search never breaks because neighbor expansion
    failed.
    """
    src = matched_meta.get('source_file')
    chunk_idx = matched_meta.get('chunk_index')
    if not src or not isinstance(chunk_idx, int):
        return {'text': matched_doc, 'drawer_index': chunk_idx, 'total_drawers': None}
    parent_id = matched_meta.get('parent_drawer_id')
    target_indexes = [chunk_idx + offset for offset in range(-radius, radius + 1)]
    neighbor_clauses = [{'source_file': src}, {'chunk_index': {'$in': target_indexes}}]
    if parent_id:
        neighbor_clauses.append({'parent_drawer_id': parent_id})
    try:
        neighbors = drawers_col.get(where={'$and': neighbor_clauses}, include=['documents', 'metadatas'])
    except Exception:
        return {'text': matched_doc, 'drawer_index': chunk_idx, 'total_drawers': None}
    indexed_docs = []
    for (doc, meta) in zip(neighbors.documents, neighbors.metadatas):
        ci = meta.get('chunk_index')
        if isinstance(ci, int):
            indexed_docs.append((ci, doc))
    indexed_docs.sort(key=lambda pair: pair[0])
    if not indexed_docs:
        combined_text = matched_doc
    else:
        combined_text = '\n\n'.join((doc for (_, doc) in indexed_docs))
    total_drawers = None
    try:
        all_meta = drawers_col.get(where=_scoped_source_filter(src, parent_id), include=['metadatas'])
        total_drawers = len(all_meta.ids) if all_meta.ids else None
    except Exception:
        logger.debug('total_drawers lookup failed for %s', src, exc_info=True)
    return {'text': combined_text, 'drawer_index': chunk_idx, 'total_drawers': total_drawers}

def _index_key_type_reason(table: dict, item: dict) -> str | None:
    """AWS's type-mismatch message for a wrong-typed / non-scalar secondary
    index key attribute in `item`, or None. Used both as a top-level
    ValidationException (single writes) and as a per-item TransactionCanceled
    ValidationError reason (transactions)."""
    attr_defs = {ad['AttributeName']: ad['AttributeType'] for ad in table.get('AttributeDefinitions') or []}
    for idx in (table.get('GlobalSecondaryIndexes') or []) + (table.get('LocalSecondaryIndexes') or []):
        idx_name = idx.get('IndexName')
        for ks in idx.get('KeySchema') or []:
            key_name = ks.get('AttributeName')
            if not key_name or key_name not in item:
                continue
            expected_type = attr_defs.get(key_name)
            if not expected_type:
                continue
            raw = item[key_name]
            if not isinstance(raw, dict) or len(raw) != 1:
                return f'One or more parameter values were invalid: Type mismatch for Index Key {key_name} Expected: {expected_type} Actual: map IndexName: {idx_name}'
            actual_type = next(iter(raw))
            if actual_type != expected_type:
                return f'One or more parameter values were invalid: Type mismatch for Index Key {key_name} Expected: {expected_type} Actual: {actual_type} IndexName: {idx_name}'
    return None

def __strip_protocol_from_url(url):
    """
    Strip the PROTOCOL specifier from an URL string and return it, along with
    the remainder of the URL.
    """
    if '://' not in url:
        return (None, url)
    parts = url.split('://', 1)
    protocol = parts[0]
    url = url.replace(parts[0] + '://', '').lstrip('/').rstrip('/')
    return (protocol, url)

def _map_single_label(label_name: str) -> str:
    """Map a single KPWr label name to standard BIO label.

    Args:
        label_name:
            The KPWr label name to map.

    Returns:
        The standard BIO label.
    """
    entity_mappings: dict[str, tuple[str, str]] = {'nam_liv': ('B-PER', 'I-PER'), 'nam_loc': ('B-LOC', 'I-LOC'), 'nam_org': ('B-ORG', 'I-ORG')}
    if label_name == 'O':
        return 'O'
    for (keyword, (b_label, i_label)) in entity_mappings.items():
        if keyword in label_name:
            if label_name.startswith('B-'):
                return b_label
            elif label_name.startswith('I-'):
                return i_label
    if label_name.startswith('B-'):
        return 'B-MISC'
    elif label_name.startswith('I-'):
        return 'I-MISC'
    return 'O'

def _normalize_host(host: str) -> str:
    """Normalize a Host header value (or allow-list entry) for comparison.

    Strips the port and any IPv6 brackets, then lowercases: ``[::1]:8900``
    becomes ``::1``, ``Example.COM:8900`` becomes ``example.com``. A value
    with more than one colon and no brackets is treated as a bare IPv6
    literal and kept whole (never split into a fake ``host:port`` pair).

    Args:
        host: Raw Host header value or allow-list entry.

    Returns:
        The comparable hostname, lowercased.
    """
    value = host.strip()
    if value.startswith('['):
        end = value.find(']')
        if end != -1:
            return value[1:end].lower()
    elif value.count(':') == 1:
        value = value.rsplit(':', 1)[0]
    return value.lower()

def header_of(text: str) -> str:
    """Return the leading comment region (blank lines inside it kept)."""
    lines = text.splitlines()
    if lines and lines[0].startswith('#!'):
        lines = lines[1:]
    out: list[str] = []
    for ln in lines:
        if ln.startswith('#') or not ln.strip():
            out.append(ln)
        else:
            break
    while out and (not out[-1].strip()):
        out.pop()
    return '\n'.join(out)

def extract_step_return(step_output):
    """Extract information for run container or script output.
    step_output is a list with multiple outputs
    """
    ret = {}
    if isinstance(step_output, list):
        step_output = step_output[0]
        if not isinstance(step_output, Output):
            ret['value'] = step_output
            return ret
        else:
            tmp = step_output.value.split('.')
            if len(tmp) < 4:
                raise ValueError('Incorrect step return representation')
            step_name = tmp[1]
            template_name = tmp[2]
            output = tmp[3]
            for item in tmp[4:]:
                output = output + '.' + item
            ret = {'name': template_name, 'id': step_name, 'output': output}
            return ret
    else:
        ret['value'] = step_output
        return ret

def _find_thermal_pads(fp: dict) -> list[dict]:
    """Identify thermal/exposed pads on a footprint.

    Returns list of pad dicts that are likely thermal pads —
    large center pads on power/ground nets, typical of QFN/BGA packages.
    """
    pads = fp.get('pads', [])
    if len(pads) < 3:
        return []
    pad_areas: list[tuple[dict, float]] = []
    for p in pads:
        if p.get('type') != 'smd':
            continue
        pad_layers = p.get('layers', [])
        if not any((l.endswith('.Cu') or l == '*.Cu' for l in pad_layers)):
            continue
        w = p.get('width', p.get('size_x', 0))
        h = p.get('height', p.get('size_y', 0))
        area = w * h
        if area > 0:
            pad_areas.append((p, area))
    if not pad_areas:
        return []
    avg_area = sum((a for (_, a) in pad_areas)) / len(pad_areas)
    all_areas_sorted = sorted((a for (_, a) in pad_areas))
    median_area = all_areas_sorted[len(all_areas_sorted) // 2]
    thermal = []
    for (p, area) in pad_areas:
        pad_num = str(p.get('number', ''))
        is_ep = pad_num in ('0', 'EP', '')
        if not is_ep and median_area > 0:
            other_areas = sorted((a for (pad, a) in pad_areas if str(pad.get('number', '')) != pad_num))
            if other_areas:
                median_signal = other_areas[len(other_areas) // 2]
                if median_signal > 0 and area >= median_signal * 3.0:
                    is_ep = True
        if not (is_ep and area >= 2.0 or area > 6.0):
            continue
        if avg_area > 0 and area < avg_area * 2.0:
            continue
        net_name = p.get('net_name', '')
        pad_net_num = p.get('net_number', -1)
        if not net_name or pad_net_num <= 0:
            continue
        net_upper = net_name.upper()
        is_power_or_gnd = net_upper in ('GND', 'VSS', 'AGND', 'DGND', 'PGND', 'VCC', 'VDD', 'AVCC', 'AVDD', 'DVCC', 'DVDD', 'VBUS') or net_upper.startswith('+') or net_upper.startswith('V+') or ('GND' in net_upper) or ('VCC' in net_upper) or ('VDD' in net_upper)
        if not is_power_or_gnd and (not is_ep):
            continue
        thermal.append(p)
    return thermal

def _ddb_size(val):
    """AWS size() returns the size of a value per AWS rules:
    - S: number of UTF-16 code units (a surrogate pair counts as 2).
    - B: number of bytes in the decoded binary value.
    - SS/NS/BS/L/M: element count.
    """
    if isinstance(val, dict):
        if 'S' in val:
            s = val['S']
            return sum((2 if ord(c) > 65535 else 1 for c in s))
        if 'B' in val:
            b = val['B']
            if isinstance(b, bytes):
                return len(b)
            try:
                import base64
                return len(base64.b64decode(b))
            except Exception:
                return len(b) if isinstance(b, str) else 0
        if 'SS' in val:
            return len(val['SS'])
        if 'NS' in val:
            return len(val['NS'])
        if 'BS' in val:
            return len(val['BS'])
        if 'L' in val:
            return len(val['L'])
        if 'M' in val:
            return len(val['M'])
    return 0

def _resolve_remote_url(remote_url: str) -> str | None:
    """Return the public base URL for the proxy, or None if unknown.

    User-supplied `remote_url` from the addon config wins; falls back to
    the Nabu Casa cloud URL when blank. The returned value is an absolute
    https URL with no trailing slash, or None when neither source has one
    (cloudflared/custom proxy users who haven't filled remote_url).
    """
    if remote_url and remote_url.strip():
        url = remote_url.strip().rstrip('/')
        if not url.startswith(('http://', 'https://')):
            url = 'https://' + url
        return url
    return get_nabu_casa_url()

def check_url(url=''):
    """
    校验URL合法性
    :param url:
    :return: 合法的URL | False
    """
    url = str(url).strip().replace('"', '').replace("'", '').replace('<', '').replace('>', '').replace(';', '').replace('\\', '/')
    if 10 < len(url) and len(url) < 40:
        if re.search(FORBIDDEN_DOMAIN, url):
            return False
        if url.startswith('http://') or url.startswith('https://'):
            url_params = url.split('/')
            domain = url_params[2]
            if domain.find('.') >= 0:
                return url.lower()
    return False

def extract_balanced_braces(text, start_pos):
    """
    Extract content from balanced braces starting at start_pos.

    This function properly handles nested braces, which is important for LaTeX content
    where patterns like {Jos{'e} Meseguer} need to be extracted as complete units.

    Args:
        text: The text to search in
        start_pos: Position of the opening brace

    Returns:
        tuple: (content, end_pos) or (None, start_pos) if no balanced content found
    """
    if start_pos >= len(text) or text[start_pos] != '{':
        return (None, start_pos)
    brace_count = 1
    pos = start_pos + 1
    while pos < len(text) and brace_count > 0:
        if text[pos] == '{':
            brace_count += 1
        elif text[pos] == '}':
            brace_count -= 1
        pos += 1
    if brace_count == 0:
        return (text[start_pos + 1:pos - 1], pos)
    else:
        return (None, start_pos)

def parse_model_format(model: str, fmt: str) -> tuple[str, str]:
    """Parse model name and format, handling @format suffix in model name.

    Some older CSV rows encode format in the model name as 'model@format'.
    Newer rows use the Tool Format column separately.
    """
    if '@' in model:
        (base, embedded_fmt) = model.rsplit('@', 1)
        return (base, embedded_fmt)
    return (model, fmt)

def GetCodeObjectAtLine(module, line):
    """Searches for a code object at the specified line in the specified module.

  Args:
    module: module to explore.
    line: 1-based line number of the statement.

  Returns:
    (True, Code object) on success or (False, (prev_line, next_line)) on
    failure, where prev_line and next_line are the closest lines with code above
    and below the specified line, or None if they do not exist.
  """
    if not hasattr(module, '__file__'):
        return (False, (None, None))
    prev_line = 0
    next_line = sys.maxsize
    for code_object in _GetModuleCodeObjects(module):
        for co_line_number in _GetLineNumbers(code_object):
            if co_line_number == line:
                return (True, code_object)
            elif co_line_number < line:
                prev_line = max(prev_line, co_line_number)
            elif co_line_number > line:
                next_line = min(next_line, co_line_number)
    prev_line = None if prev_line == 0 else prev_line
    next_line = None if next_line == sys.maxsize else next_line
    return (False, (prev_line, next_line))

def compare(obj1, obj2):
    """
        Compare 2 objects.
        Return True if they are equal and False otherwise.
        This code is really ugly, more elegant way to do that??
    """
    try:
        attributes_1 = sorted([x for x in obj1.class_trait_names()])
        attributes_2 = sorted([x for x in obj2.class_trait_names()])
    except:
        try:
            return obj1.default_value == obj2.default_value
        except:
            return obj1 == obj2
    if attributes_1 != attributes_2:
        return False
    for attribute in attributes_1:
        if isinstance(getattr(obj1, attribute), list):
            if isinstance(getattr(obj2, attribute), list):
                if len(getattr(obj1, attribute)) != len(getattr(obj2, attribute)):
                    return False
                else:
                    for (x, y) in zip(getattr(obj1, attribute), getattr(obj2, attribute)):
                        return compare(x, y)
            else:
                return False
        elif isinstance(getattr(obj2, attribute), list):
            if isinstance(getattr(obj1, attribute), list):
                pass
            elif len(getattr(obj1, attribute)) != len(getattr(obj2, attribute)):
                return False
            else:
                for (x, y) in zip(getattr(obj1, attribute), getattr(obj2, attribute)):
                    return compare(x, y)
        elif getattr(obj1, attribute) != getattr(obj2, attribute):
            return False
    return True

def retry_delay(attempt: int, rate_limited: bool) -> int:
    """Return the retry delay for a given attempt."""
    if rate_limited:
        return RETRY_BASE_DELAY * RETRY_BACKOFF ** attempt
    return 5

def _tenant_is_unwired(tenant) -> bool:
    """A default tenant is UNWIRED iff BOTH its dev and prod stages have an empty
    ``deploy_role_arn`` AND an empty ``ecr_repo_uri`` — i.e. it is provably
    untouched-by-wiring. Any non-empty deploy-role/ecr on either stage means an
    operator (or a prior wired run) has already set it, so we treat it as wired and
    never overwrite it. Missing stages (a hand-edited/legacy record) also count as
    NOT unwired, so we err on the side of leaving it alone."""
    stages = getattr(tenant, 'stages', None) or {}
    if not {'dev', 'prod'} <= set(stages):
        return False
    for key in ('dev', 'prod'):
        stage = stages[key]
        if getattr(stage, 'deploy_role_arn', '') or getattr(stage, 'ecr_repo_uri', ''):
            return False
    return True

def add_key(base, new, base_name, new_name, device=None):
    """ Add new keys to the given input

    Args:
        base (tensor): inputs
        new (tensor): new info for the inputs
        base_name (str): name for the input
        new_name (str): name for the new info
        device (device): pytorch device
    """
    if new is not None and isinstance(new, dict):
        if device is not None:
            for key in new.keys():
                new[key] = new[key].to(device)
        base = {base_name: base, new_name: new}
    return base

def _material_spec(mesh) -> tuple:
    """A hashable description of one mesh's appearance: ('tex', name) or ('rgba', r, g, b, a).

    glTF's `baseColorFactor` arrives here on 0-255 while MuJoCo wants 0-1, and a factor is present
    even on meshes that also carry an image — the texture wins when there is one.
    """
    visual = getattr(mesh, 'visual', None)
    material = getattr(visual, 'material', None)
    if material is None:
        return ('rgba', 0.7, 0.7, 0.7, 1.0, '')
    image = getattr(material, 'baseColorTexture', None) or getattr(material, 'image', None)
    uv = getattr(visual, 'uv', None)
    name = getattr(material, 'name', None) or ''
    if image is not None and uv is not None and len(uv):
        return ('tex', name or f'tex{id(image):x}', image)
    factor = getattr(material, 'baseColorFactor', None)
    if factor is None:
        return ('rgba', 0.7, 0.7, 0.7, 1.0, name)
    values = [float(v) for v in np.asarray(factor, dtype=float).ravel()[:4]]
    while len(values) < 4:
        values.append(255.0)
    scale = 255.0 if max(values) > 1.001 else 1.0
    return ('rgba', *[round(v / scale, 4) for v in values], name)

def get_prop_type(value, key=None):
    """
    Performs typing and value conversion for the graph_tool PropertyMap class.
    If a key is provided, it also ensures the key is in a format that can be
    used with the PropertyMap. Returns a tuple, (type name, value, key).

    This function is adapted from Benjamin Bengfort's blog post!
    https://bbengfort.github.io/2016/06/graph-tool-from-networkx/
    """
    if isinstance(key, str):
        key = key
    if isinstance(value, bool):
        tname = 'bool'
    elif isinstance(value, int):
        tname = 'float'
        value = float(value)
    elif isinstance(value, float):
        tname = 'float'
    elif isinstance(value, str):
        tname = 'string'
    elif isinstance(value, bytes):
        tname = 'bytes'
    elif isinstance(value, dict):
        tname = 'object'
    else:
        tname = 'string'
        value = str(value)
    return (tname, value, key)

def _url_is_valid(url: str) -> bool:
    """Checks whether the given `url` is acceptable:
       * url is can be parsed without an error.
       * url uses a supported scheme / protocol.
    """
    try:
        u = urlparse(url)
    except:
        return False
    if u.scheme not in _SUPPORTED_SCHEMES:
        return False
    return True

def _compile(filt):
    """Return a string represented the compiled filter function"""
    if not filt:
        return 'True'
    op = filt[0]
    if len(filt) == 1:
        return 'False' if op == 'any' else 'True'
    if op in ['==', '!=', '<', '>', '<=', '>=']:
        return _compile_comparison_op(filt[1], filt[2], op)
    elif op == 'any':
        return _compile_logical_op(filt[1:], ' or ')
    elif op == 'all':
        return _compile_logical_op(filt[1:], ' and ')
    elif op == 'none':
        return _compile_negation(_compile_logical_op(filt[1:], ' or '))
    elif op == 'in':
        return _compile_in_op(filt[1], filt[2:])
    elif op == '!in':
        return _compile_negation(_compile_in_op(filt[1], filt[2:]))
    elif op == 'has':
        return _compile_has_op(filt[1])
    elif op == '!has':
        return _compile_negation(_compile_has_op(filt[1]))
    return 'True'

def short_repr(obj, noneAsNA=False):
    """Return a short representation of obj for clarity."""
    if obj is None:
        return 'unspecified' if noneAsNA else 'None'
    if isinstance(obj, str) and len(obj) > 80:
        return '{}...{}'.format(obj[:60].replace('\n', '\\n'), obj[-20:].replace('\n', '\\n'))
    if isinstance(obj, (str, int, float, bool)):
        return repr(obj)
    if hasattr(obj, '__short_repr__'):
        return obj.__short_repr__()
    if isinstance(obj, Sequence):
        if len(obj) == 0:
            return '[]'
        if len(obj) == 1:
            return f'{short_repr(obj[0])}'
        if len(obj) == 2:
            return f'{short_repr(obj[0])}, {short_repr(obj[1])}'
        return f'{short_repr(obj[0])}, {short_repr(obj[1])}, ... ({len(obj)} items)'
    if isinstance(obj, dict):
        if not obj:
            return ''
        if len(obj) == 1:
            first_key = list(obj.keys())[0]
            return f'{short_repr(first_key)!r}:{short_repr(obj[first_key])!r}'
        first_key = list(obj.keys())[0]
        return f'{short_repr(first_key)}:{short_repr(obj[first_key])}, ... ({len(obj)} items)'
    if isinstance(obj, KeysView):
        if not obj:
            return ''
        if len(obj) == 1:
            return short_repr(next(iter(obj)))
        return f'{short_repr(next(iter(obj)))}, ... ({len(obj)} items)'
    ret = str(obj)
    if len(ret) > 40:
        return f'{repr(obj)[:35]}...'
    return ret

def split_qualified(fqname):
    """
    Split a fully qualified element name, in Clark's notation, into its URI and
    local name components.

    :param fqname: Fully qualified name in Clark's notation.
    :return: 2-tuple containing the namespace URI and local tag name.
    """
    if fqname and fqname[0] == '{':
        return tuple(fqname[1:].split('}'))
    return (None, fqname)

def scale_img(img, ratio=1.0, same_shape=False, gs=32):
    """Scales and pads an image tensor of shape img(bs,3,y,x) based on given ratio and grid size gs, optionally
    retaining the original shape.
    """
    if ratio == 1.0:
        return img
    (h, w) = img.shape[2:]
    s = (int(h * ratio), int(w * ratio))
    img = F.interpolate(img, size=s, mode='bilinear', align_corners=False)
    if not same_shape:
        (h, w) = (math.ceil(x * ratio / gs) * gs for x in (h, w))
    return F.pad(img, [0, w - s[1], 0, h - s[0]], value=0.447)

def build_filters(award_types=None, start_date=None, end_date=None, recipient=None, agency=None):
    """
    Build a filters dictionary for the API request.

    Args:
        award_types: List of award type codes (e.g., ["A", "B", "C"] for contracts)
        start_date: Start date string (YYYY-MM-DD)
        end_date: End date string (YYYY-MM-DD)
        recipient: Recipient name search string
        agency: Awarding agency name search string

    Returns:
        Filters dictionary for API request
    """
    filters = {}
    if award_types:
        filters['award_type_codes'] = award_types
    if start_date or end_date:
        time_period = {}
        if start_date:
            time_period['start_date'] = start_date
        if end_date:
            time_period['end_date'] = end_date
        filters['time_period'] = [time_period]
    if recipient:
        filters['recipient_search_text'] = [recipient]
    if agency:
        filters['agencies'] = [{'type': 'awarding', 'tier': 'toptier', 'name': agency}]
    return filters

def resolve_url_and_token_variables(jupyter_url, jupyter_token, document_url, document_token, code_sandbox_url, code_sandbox_token) -> tuple[str | None, str | None, str, str | None]:
    """Resolve merged URL/token settings with per-field precedence.

    ``resolved_document_url`` may be ``None`` when neither ``document_url``
    nor ``jupyter_url`` is given; callers (and JupyterMCPConfig) fall back to
    the code sandbox URL in that case rather than hardcoding localhost.
    """
    if document_url is not None:
        resolved_document_url = document_url
    elif jupyter_url is not None:
        resolved_document_url = jupyter_url
    else:
        resolved_document_url = None
    if code_sandbox_url is not None:
        resolved_code_sandbox_url = code_sandbox_url
    elif jupyter_url is not None:
        resolved_code_sandbox_url = jupyter_url
    else:
        resolved_code_sandbox_url = 'http://localhost:8888'
    resolved_document_token = document_token or jupyter_token
    resolved_code_sandbox_token = code_sandbox_token or jupyter_token
    return (resolved_document_url, resolved_document_token, resolved_code_sandbox_url, resolved_code_sandbox_token)

