def _clean_cell(cell: dict) -> dict:
    """Drop run-specific metadata, stderr noise, and text/plain fallbacks that shadow a rich output."""
    cell['metadata'] = {k: v for (k, v) in cell.get('metadata', {}).items() if k != 'execution'}
    outputs = []
    for out in cell.get('outputs', []):
        if out.get('output_type') == 'stream' and out.get('name') == 'stderr':
            text = _TQDM_NOISE.sub('', ''.join(out.get('text', [])))
            if not text:
                continue
            out['text'] = text
        data = out.get('data')
        if data and ('text/html' in data or any((k.startswith('image/') for k in data))):
            data.pop('text/plain', None)
        outputs.append(out)
    cell['outputs'] = outputs
    return cell

def _clean_dict(d):
    """
        Recursively clean a dictionary by removing all None values, empty strings, empty lists,
        and nested dictionaries that become empty after cleaning.

        Args:
            d (dict): The dictionary to clean.

        Returns:
            dict: The cleaned dictionary.
        """
    if not isinstance(d, dict):
        return d
    cleaned_dict = {}
    for (key, value) in d.items():
        if isinstance(value, dict):
            nested_cleaned = _clean_dict(value)
            if nested_cleaned:
                cleaned_dict[key] = nested_cleaned
        elif isinstance(value, bool) or value:
            cleaned_dict[key] = value
    return cleaned_dict

@staticmethod
def _is_placeholder_stock_name(name: str, code: str) -> bool:
    """Return True when the stock name is missing or placeholder-like."""
    if not name:
        return True
    normalized = str(name).strip()
    if not normalized:
        return True
    if normalized == code:
        return True
    if normalized.startswith('股票'):
        return True
    if 'Unknown' in normalized:
        return True
    return False

@staticmethod
def match(o1, o2):
    """
        Compare two ModelDescription object instances

        Arguments:
            o1 (ModelDescription, dict): object to compare
            o2 (ModelDescription, dict): object to compare

        Returns:
            bool: true if objects match
        """
    type_o1 = type(o1)
    if type_o1 is not type(o2):
        return False
    if type_o1 is dict:
        if set(o1.keys()) != set(o2.keys()):
            neon_logger.display('Missing keys')
            return False
        for key in o1:
            if key == 'name':
                return True
            if not ModelDescription.match(o1[key], o2[key]):
                return False
    elif any([type_o1 is x for x in [list, tuple]]):
        if len(o1) != len(o2):
            return False
        for (val1, val2) in zip(o1, o2):
            if not ModelDescription.match(val1, val2):
                return False
    elif type_o1 is np.ndarray:
        match = np.array_equal(o1, o2)
        return match
    else:
        return o1 == o2
    return True

